//! The Rust emitter: IR -> the source files of the `ngap-types` crate.
//!
//! [`emit`] returns the complete set of generated files (path relative to the crate's `src/`, and content). The
//! caller writes them (`cargo xtask gen`) or compares them with the committed ones (`cargo xtask check`).

mod generator;
mod names;

pub use generator::EmitError;

use crate::ir::Ir;
use generator::{Generator, Item};

/// One generated file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GeneratedFile {
    /// Relative to the crate's `src/` directory.
    pub path: String,
    pub content: String,
}

/// Marks files written by the generator (also lets `gen` delete stale ones without touching hand-written files).
pub const GENERATED_MARKER: &str = "@generated by ngap-codegen";

/// Rough size of one generated file, in lines; items are never split.
const CHUNK_LINES: usize = 2500;

const FILE_HEADER: &str = "// @generated by ngap-codegen from 3GPP TS 38.413 (see codegen/spec-source.toml). DO NOT EDIT:\n// change the generator and run `cargo xtask gen`.\n#![cfg_attr(rustfmt, rustfmt::skip)]\n";

/// Generate every file of `ngap-types/src`.
pub fn emit(ir: &Ir) -> Result<Vec<GeneratedFile>, EmitError> {
    let mut g = Generator::new(ir)?;
    g.run()?;
    let constants = g.constants_code()?;

    let mut files = Vec::new();
    let mut modules: Vec<String> = Vec::new();

    files.push(GeneratedFile {
        path: "constants.rs".into(),
        content: format!("{FILE_HEADER}{constants}"),
    });
    modules.push("constants".into());

    // group items by ASN.1 module (in first-seen order), then split each group into chunks
    let mut groups: Vec<(String, Vec<&Item>)> = Vec::new();
    for item in &g.items {
        match groups.iter_mut().find(|(n, _)| *n == item.group) {
            Some((_, v)) => v.push(item),
            None => groups.push((item.group.clone(), vec![item])),
        }
    }
    for (group, items) in &groups {
        let base = group.to_ascii_lowercase().replace('-', "_");
        let mut chunk: Vec<&Item> = Vec::new();
        let mut lines = 0;
        let flush = |chunk: &mut Vec<&Item>,
                     files: &mut Vec<GeneratedFile>,
                     modules: &mut Vec<String>| {
            if chunk.is_empty() {
                return;
            }
            let name = format!(
                "{base}_{:02}",
                modules.iter().filter(|m| m.starts_with(&base)).count()
            );
            let mut content = String::from(FILE_HEADER);
            content.push_str("use ngap_aper as rt;\nuse rt::{AperDecode as _, AperEncode as _};\nuse crate::*;\n");
            for it in chunk.iter() {
                content.push('\n');
                content.push_str(&it.code);
            }
            files.push(GeneratedFile {
                path: format!("{name}.rs"),
                content,
            });
            modules.push(name);
            chunk.clear();
        };
        for it in items {
            let n = it.code.lines().count() + 1;
            if lines + n > CHUNK_LINES {
                flush(&mut chunk, &mut files, &mut modules);
                lines = 0;
            }
            chunk.push(it);
            lines += n;
        }
        flush(&mut chunk, &mut files, &mut modules);
    }

    let mut lib = String::from(FILE_HEADER);
    lib.push_str("//! Typed definitions of every message and information element of 3GPP TS 38.413 (NGAP), with ALIGNED PER\n//! encoding and decoding (`ngap_aper::AperEncode` / `AperDecode`). Generated from the ASN.1 of the specification.\n//!\n//! Names follow `docs/mapping-rules.md`: `NGSetupRequest` is `NgSetupRequest`, the IEs of a message are its fields.\n\n#![allow(unused_imports, unused_variables, clippy::all)]\n\npub use ngap_aper::ie::Criticality;\n\n");
    for m in &modules {
        lib.push_str(&format!("mod {m};\npub use {m}::*;\n"));
    }
    files.push(GeneratedFile {
        path: "lib.rs".into(),
        content: lib,
    });
    Ok(files)
}

